actor DurableOutbox {
  func enqueue(_ msg: Message) throws {
    let url = spoolURL(msg.id)
    try JSONEncoder().encode(msg).write(to: url, options: .atomic)  // temp + rename
    let h = try FileHandle(forWritingTo: url)
    try h.synchronizeFile()          // fsync: this is the commit point
    try h.close()
  }
  func acknowledge(_ id: MessageID) throws {
    try FileManager.default.removeItem(at: spoolURL(id))
  }
}

